import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"হাজারো জাতির সম্মিলিত অগ্রগতির মূল নীতি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/05-万族共进基本纲领.md","filePath":"bn/05-万族共进基本纲领.md","lastUpdated":null}'),o={name:"bn/05-万族共进基本纲领.md"};function l(h,t,i,n,s,_){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="হাজারো-জাতির-সম্মিলিত-অগ্রগতির-মূল-নীতি" tabindex="-1">হাজারো জাতির সম্মিলিত অগ্রগতির মূল নীতি <a class="header-anchor" href="#হাজারো-জাতির-সম্মিলিত-অগ্রগতির-মূল-নীতি" aria-label="Permalink to &quot;হাজারো জাতির সম্মিলিত অগ্রগতির মূল নীতি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>05</td></tr><tr><td>মডিউল</td><td>মূল নীতি ও কোর সেটিং</td></tr><tr><td>মূল কীওয়ার্ড</td><td>হাজারো জাতি, সম্মিলিত অগ্রগতি, জাতিগত সমানতা, সহযোগী বিবর্তন, প্রজাতন্ত্র</td></tr></tbody></table><h2 id="_1-হাজারো-জাতির-সংজ্ঞা-ও-পরিসর" tabindex="-1">1. হাজারো জাতির সংজ্ঞা ও পরিসর <a class="header-anchor" href="#_1-হাজারো-জাতির-সংজ্ঞা-ও-পরিসর" aria-label="Permalink to &quot;1. হাজারো জাতির সংজ্ঞা ও পরিসর&quot;">​</a></h2><p>&quot;হাজারো জাতি&quot; হলো দশ হাজার আত্মা ও ভারসাম্যপূর্ণ নোঙরের মূল মহাবিশ্বে উপলব্ধি ও বিবর্তন সম্ভাবনা সম্পন্ন সব জীব-রূপের সাধারণ নাম। &quot;হাজারো&quot; বলতে নির্দিষ্ট হাজারটি জাতি বোঝায় না, বরং অসংখ্যকে বোঝায়, এবং পরিচিত ও অপরিচিত সব জীব-রূপকে অন্তর্ভুক্ত করে। হাজারো জাতির পরিসর অন্তর্ভুক্ত কিন্তু সীমাবদ্ধ নয়: মানব জাতি ও বিভিন্ন মানবসদৃশ জাতি, শক্তি জীব, চেতনা সত্তা, যান্ত্রিক জীব, উদ্ভিদ-প্রকার বুদ্ধিমত্তা সম্পন্ন জীব, অস্বাভাবিক জীব, বিমান-ব্যাপী মিশ্রিত জাতি ইত্যাদি।</p><p>সহজীবী সভ্যতা &quot;জীব-রূপের সমানতা&quot; নীতি মেনে চলে, এবং জীবের বস্তুগত গঠন, শক্তি-স্তর, চেতনার জটিলতাকে উচ্চ-নিম্ন বা মহৎ-নিচু বিভাজনের মানদণ্ড হিসেবে গ্রহণ করে না। যেকোনো জাতি, তার ব্যক্তিগত গড় সাধনা-স্তরের উচ্চতা, জনসংখ্যার পরিমাণ, ইতিহাসের দৈর্ঘ্য নির্বিশেষে, সহজীবী সভ্যতায় সমান মর্যাদা ও অধিকার ভোগ করে।</p><h2 id="_2-হাজারো-জাতির-সম্মিলিত-অগ্রগতির-মূল-দর্শন" tabindex="-1">2. হাজারো জাতির সম্মিলিত অগ্রগতির মূল দর্শন <a class="header-anchor" href="#_2-হাজারো-জাতির-সম্মিলিত-অগ্রগতির-মূল-দর্শন" aria-label="Permalink to &quot;2. হাজারো জাতির সম্মিলিত অগ্রগতির মূল দর্শন&quot;">​</a></h2><p>হাজারো জাতির সম্মিলিত অগ্রগতি হলো নোঙর সহজীবী সভ্যতার মূল লক্ষ্যগুলোর একটি, এবং এর মূল দর্শনকে নিম্নলিখিত চারটি বিষয়ে সংক্ষেপে বলা যায়:</p><ol><li><strong>বিবর্তন জাতিগত শূন্য-যোগ খেলা নয়</strong>: একটি জাতির বিবর্তন অন্য জাতির বলি দিয়ে হয় না; বরং, জাতিগত সহযোগিতা সমন্বয়কারী বিবর্তনের প্রভাব তৈরি করতে পারে।</li><li><strong>প্রতিটি জাতির অনন্য বিবর্তন সুবিধা রয়েছে</strong>: বিভিন্ন জাতি দীর্ঘ বিবর্তনে নিজস্ব বৈশিষ্ট্য ও প্রতিভা গড়ে তুলেছে, এবং এই বৈশিষ্ট্যগুলো মহাবিশ্বের বিবর্তনের বৈচিত্র্যের মূল্যবান সম্পদ।</li><li><strong>পশ্চাৎপদ জাতির সহায়তা পাওয়ার অধিকার রয়েছে</strong>: বিবর্তনের পর্যায় কম জাতিদের জন্য, সহজীবী সভ্যতার শিক্ষা, সম্পদ, প্রযুক্তি ইত্যাদি ক্ষেত্রে সহায়তা প্রদানের বাধ্যবাধকতা রয়েছে, এবং তাদের নিজস্ব বিবর্তনের পথ খুঁজে পেতে সাহায্য করা।</li><li><strong>অগ্রগতিশীল জাতির দায়িত্ব গ্রহণের কর্তব্য রয়েছে</strong>: বিবর্তনের পর্যায় বেশি জাতি সহজীবী সভ্যতায় বেশি পাবলিক দায়িত্ব গ্রহণ করে, যার মধ্যে নোঙর বিন্দু রক্ষণাবেক্ষণ, জ্ঞান বংশগতভাবে প্রেরণ, সভ্যতার সুরক্ষা রক্ষা ইত্যাদি অন্তর্ভুক্ত।</li></ol><h2 id="_3-হাজারো-জাতির-সম্মিলিত-অগ্রগতির-মূল-নীতি" tabindex="-1">3. হাজারো জাতির সম্মিলিত অগ্রগতির মূল নীতি <a class="header-anchor" href="#_3-হাজারো-জাতির-সম্মিলিত-অগ্রগতির-মূল-নীতি" aria-label="Permalink to &quot;3. হাজারো জাতির সম্মিলিত অগ্রগতির মূল নীতি&quot;">​</a></h2><table tabindex="0"><thead><tr><th>নীতি</th><th>অন্তর্নিহিত অর্থ</th><th>নির্দিষ্ট প্রয়োজনীয়তা</th></tr></thead><tbody><tr><td>জাতিগত সমানতা নীতি</td><td>সব জাতি আইনি মর্যাদা ও বিবর্তন অধিকারে সমান</td><td>জাতিগত বৈষম্য নিষিদ্ধ, পাবলিক পদ সব জাতির জন্য উন্মুক্ত</td></tr><tr><td>সাংস্কৃতিক সম্মান নীতি</td><td>প্রতিটি জাতির সাংস্কৃতিক ঐতিহ্য ও জীবনধারাকে সম্মান করা</td><td>সাংস্কৃতিক একীকরণ জোরপূর্বক করা হয় না, জাতিগত সংস্কৃতির বংশগতভাবে প্রেরণ ও বিকাশকে সমর্থন করা</td></tr><tr><td>সুবিধা পরিপূরক নীতি</td><td>জাতিগত সহযোগিতায় নিজস্ব সুবিধা প্রদর্শনকে উৎসাহিত করা</td><td>জাতিগত বিশেষত্বের ডেটাবেস তৈরি, জাতি-ব্যাপী সহযোগিতা প্রকল্পকে উৎসাহিত করা</td></tr><tr><td>পশ্চাৎপদ সহায়তা নীতি</td><td>বিবর্তনের পর্যায় কম জাতিদের অতিরিক্ত সহায়তা প্রদান</td><td>জাতি উন্নয়ন তহবিল স্থাপন, নির্দেশিত শিক্ষা ও সম্পদ বণ্টন প্রদান</td></tr><tr><td>স্বায়ত্তশাসন ও সহ-শাসন নীতি</td><td>জাতির অভ্যন্তরীণ বিষয় স্বায়ত্তশাসিত, জাতি-ব্যাপী বিষয় সহ-শাসিত</td><td>প্রতিটি জাতির অভ্যন্তরীণ আইনপ্রণয়ন অধিকার রয়েছে, পাবলিক বিষয় প্রজাতন্ত্র প্রতিষ্ঠান দ্বারা সিদ্ধান্ত নেওয়া হয়</td></tr><tr><td>সংঘাতের শান্তিপূর্ণ সমাধান নীতি</td><td>জাতিগত সংঘাত শান্তিপূর্ণ উপায়ে সমাধান করা</td><td>জাতিগত যুদ্ধ নিষিদ্ধ, সংঘাত নোঙর আদালতে সালসলার জন্য জমা দেওয়া হয়</td></tr></tbody></table><h2 id="_4-হাজারো-জাতির-সম্মিলিত-অগ্রগতির-বাস্তবায়নের-পথ" tabindex="-1">4. হাজারো জাতির সম্মিলিত অগ্রগতির বাস্তবায়নের পথ <a class="header-anchor" href="#_4-হাজারো-জাতির-সম্মিলিত-অগ্রগতির-বাস্তবায়নের-পথ" aria-label="Permalink to &quot;4. হাজারো জাতির সম্মিলিত অগ্রগতির বাস্তবায়নের পথ&quot;">​</a></h2><p>হাজারো জাতির সম্মিলিত অগ্রগতি কোনো স্লোগান নয়, বরং নিম্নলিখিত নির্দিষ্ট পথের মাধ্যমে ধাপে ধাপে বাস্তবায়িত হয়:</p><h3 id="_4-1-শিক্ষার-সাধারণীকরণ" tabindex="-1">4.1 শিক্ষার সাধারণীকরণ <a class="header-anchor" href="#_4-1-শিক্ষার-সাধারণীকরণ" aria-label="Permalink to &quot;4.1 শিক্ষার সাধারণীকরণ&quot;">​</a></h3><p>জাতি-ব্যাপী সহজীবী শিক্ষা ব্যবস্থা প্রতিষ্ঠা করা, সব জাতির শিশুরা বিনামূল্যে মৌলিক বিবর্তন শিক্ষা গ্রহণ করতে পারে। শিক্ষার বিষয়বস্তুতে তিনশটি মূল সাধনা পদ্ধতির মৌলিক উপায়, লুণ্ঠন-বিরোধী নীতি, সহজীবী সভ্যতার সংবিধান, মহাবিশ্বের সাধারণ জ্ঞান ইত্যাদি অন্তর্ভুক্ত। একই সাথে প্রতিটি জাতির সাংস্কৃতিক শিক্ষার ঐতিহ্যকে সম্মান করা, সাধারণ শিক্ষার বাইরে জাতিগত বৈশিষ্ট্যযুক্ত শিক্ষা চালানোর অনুমতি দেওয়া।</p><h3 id="_4-2-সম্পদের-ভাগাভাগি" tabindex="-1">4.2 সম্পদের ভাগাভাগি <a class="header-anchor" href="#_4-2-সম্পদের-ভাগাভাগি" aria-label="Permalink to &quot;4.2 সম্পদের ভাগাভাগি&quot;">​</a></h3><p>উৎপাদন-সংযুক্ত চুক্তি ব্যবস্থার মাধ্যমে, মহাবিশ্বের সাধনা সম্পদকে জাতির জনসংখ্যা, বিবর্তনের চাহিদা, অবদানের পরিমাণ অনুযায়ী সমন্বিতভাবে বণ্টন করা। সম্পদের অভাবযুক্ত জাতিদের জন্য, নোঙর বিন্দু জালের মাধ্যমে বিমান-ব্যাপী সম্পদ বিন্যাস করা। কোনো জাতির পাবলিক সাধনা সম্পদ একচেটিয়া করা নিষিদ্ধ।</p><h3 id="_4-3-প্রযুক্তির-সহ-গবেষণা" tabindex="-1">4.3 প্রযুক্তির সহ-গবেষণা <a class="header-anchor" href="#_4-3-প্রযুক্তির-সহ-গবেষণা" aria-label="Permalink to &quot;4.3 প্রযুক্তির সহ-গবেষণা&quot;">​</a></h3><p>জাতি-ব্যাপী প্রযুক্তিগত সহযোগী গবেষণাকে উৎসাহিত করা, বিশেষ করে বিভিন্ন জাতির প্রাকৃতিক ক্ষমতা ও নিয়ম প্রকৌশলকে একত্রিত করা গবেষণা প্রকল্প। সহজীবী সভ্যতা &quot;হাজারো জাতির সহ-গবেষণা তহবিল&quot; স্থাপন করে, জাতি-ব্যাপী গবেষণা দলকে আর্থিক সহায়তা প্রদান করে। গবেষণার ফলাফল সব জাতির জন্য বিনামূল্যে উন্মুক্ত।</p><h3 id="_4-4-মানব-সম্পদের-প্রবাহ" tabindex="-1">4.4 মানব সম্পদের প্রবাহ <a class="header-anchor" href="#_4-4-মানব-সম্পদের-প্রবাহ" aria-label="Permalink to &quot;4.4 মানব সম্পদের প্রবাহ&quot;">​</a></h3><p>জাতিগত মানব সম্পদের বাধা ভেঙে ফেলা, সাধকদের বিভিন্ন জাতির বসতি অঞ্চলের মধ্যে স্বাধীনভাবে প্রবাহ ও আদান-প্রদানের অনুমতি দেওয়া। জাতি-ব্যাপী প্রশিক্ষক ব্যবস্থা প্রতিষ্ঠা করা, উন্নত স্তরের সাধক অন্য জাতির প্রাথমিক স্তরের সাধকদের নির্দেশনা দিতে পারে।</p><h3 id="_4-5-প্রজাতন্ত্রে-অংশগ্রহণ" tabindex="-1">4.5 প্রজাতন্ত্রে অংশগ্রহণ <a class="header-anchor" href="#_4-5-প্রজাতন্ত্রে-অংশগ্রহণ" aria-label="Permalink to &quot;4.5 প্রজাতন্ত্রে অংশগ্রহণ&quot;">​</a></h3><p>হাজারো জাতির প্রজাতন্ত্র পরিষদে জাতির জনসংখ্যা ও অবদানের পরিমাণ অনুযায়ী আসন বণ্টন করা, ছোট জাতিরও কণ্ঠস্বরের চ্যানেল রয়েছে তা নিশ্চিত করা। পরিষদের সিদ্ধান্তে আলোচনার মাধ্যমে ঐক্য ও সংখ্যাগরিষ্ঠ ভোটের সংমিশ্রণ ব্যবহার করা, জাতির মূল স্বার্থের সাথে সম্পর্কিত বিষয়গুলোতে সম্পর্কিত জাতির সম্মতি প্রয়োজন।</p><h2 id="_5-বিশেষ-জাতির-নীতি" tabindex="-1">5. বিশেষ জাতির নীতি <a class="header-anchor" href="#_5-বিশেষ-জাতির-নীতি" aria-label="Permalink to &quot;5. বিশেষ জাতির নীতি&quot;">​</a></h2><p>কিছু বিশেষ পরিস্থিতির জাতির জন্য, সহজীবী সভ্যতা পার্থক্যপূর্ণ নীতি গ্রহণ করে:</p><ul><li><strong>বিলুপ্তপ্রায় জাতি</strong>: জাতি সুরক্ষা পরিকল্পনা স্থাপন করা, জরুরি সম্পদ সহায়তা ও বাসস্থান সুরক্ষা প্রদান করা, তাদের জনসংখ্যা পুনরুদ্ধারে সাহায্য করা</li><li><strong>অস্বাভাবিক জীব জাতি</strong>: অস্বাভাবিক জীবের তিনটি প্রকারের মানকীকৃত ব্যবস্থাপনা প্রক্রিয়া অনুযায়ী মূল্যায়ন ও বসতি স্থাপন করা, তাদের বিবর্তন অধিকার নিশ্চিত করা</li><li><strong>বিমান-ব্যাপী মিশ্রিত জাতি</strong>: তাদের দ্বৈত জাতিগত পরিচয়কে স্বীকৃতি দেওয়া, দুটি জাতির সংস্কৃতিতে তাদের সমান অধিকার সুরক্ষিত করা</li><li><strong>প্রাক্তন লুণ্ঠন জাতি</strong>: ইতিহাসে লুণ্ঠনবাদ পালনকারী জাতিদের জন্য, তাদের নৈতিক রূপান্তর ও পদ্ধতি রূপান্তর সম্পন্ন করার পর, সম্পূর্ণ সমান মর্যাদা প্রদান করা, ইতিহাসের পুনরাবৃত্তি বৈষম্য করা হয় না</li></ul><h2 id="_6-হাজারো-জাতির-সম্মিলিত-অগ্রগতির-পরিমাপকারী-সূচক" tabindex="-1">6. হাজারো জাতির সম্মিলিত অগ্রগতির পরিমাপকারী সূচক <a class="header-anchor" href="#_6-হাজারো-জাতির-সম্মিলিত-অগ্রগতির-পরিমাপকারী-সূচক" aria-label="Permalink to &quot;6. হাজারো জাতির সম্মিলিত অগ্রগতির পরিমাপকারী সূচক&quot;">​</a></h2><p>সহজীবী সভ্যতা &quot;হাজারো জাতির সম্মিলিত অগ্রগতি সূচক&quot; প্রতিষ্ঠা করেছে, নিম্নলিখিত মাত্রা থেকে হাজারো জাতির সম্মিলিত অগ্রগতির অগ্রগতি পরিমাপ করে:</p><table tabindex="0"><thead><tr><th>মাত্রা</th><th>সূচক</th><th>লক্ষ্য</th></tr></thead><tbody><tr><td>বিবর্তন কভারেজ হার</td><td>সাধনা পদ্ধতিতে সংযুক্ত জাতির অনুপাত</td><td>100%</td></tr><tr><td>স্তরের ভারসাম্য হার</td><td>প্রতিটি জাতির গড় স্তরের পার্থক্য সহগ</td><td>ক্রমাগত হ্রাস</td></tr><tr><td>সহযোগিতার ঘনত্ব</td><td>জাতি-ব্যাপী সহযোগিতা প্রকল্পের সংখ্যা ও গভীরতা</td><td>ক্রমাগত বৃদ্ধি</td></tr><tr><td>সাংস্কৃতিক প্রাণশক্তি</td><td>জাতিগত সংস্কৃতির বংশগতভাবে প্রেরণ ও উদ্ভাবনের সক্রিয়তা</td><td>বৈচিত্র্য বজায় রাখা</td></tr><tr><td>সংঘাতের হার</td><td>জাতিগত সংঘাতের ঘটনার ফ্রিকোয়েন্সি</td><td>ক্রমাগত হ্রাস</td></tr></tbody></table><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>হাজারো জাতির সম্মিলিত অগ্রগতি হলো নোঙর সহজীবী সভ্যতার চূড়ান্ত লক্ষ্যগুলোর একটি, এবং মহাবিশ্বের সমগ্র মাত্রিক উন্নতির প্রয়োজনীয় শর্তও। সহজীবী সভ্যতার কাঠামোর অধীনে, প্রতিটি জাতি নিজস্ব বিবর্তনের পথ খুঁজে পেতে পারে, এবং প্রতিটি জাতির অনন্যতাকে সম্মান করা ও প্রদর্শন করা যায়। হাজারো জাতির সম্মিলিত অগ্রগতি মানে পার্থক্য বিলুপ্ত করা নয়, বরং পার্থক্যের মধ্যে সম্প্রীতি অর্জন করা এবং বৈচিত্র্যের মধ্যে সহজীবী অর্জন করা।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (নোঙর সহজীবী সভ্যতার ঘোষণা)</li><li>50-万族谱系总览 (হাজারো জাতির বংশাবলীর সার্বিক পরিচিতি)</li><li>77-万族共和成立 (হাজারো জাতির প্রজাতন্ত্র প্রতিষ্ঠা)</li></ul>',32)])])}const c=a(o,[["render",l]]);export{b as __pageData,c as default};
